	// Read only, served locally once this replica has executed up to the client's mininstance.
	@Override
	public void balance (DidaTradeMain.BalanceRequest request, StreamObserver<DidaTradeMain.BalanceReply> responseObserver) {
		// for debug purposes
		System.out.println ("Receiving balance request:" + request);

		int reqid = request.getReqid ();
		int uid = request.getUserid ();
		int minExecutedInstance = request.getMininstance ();

		// for debug purposes
		System.out.println ("reqid " + reqid + " userid " + uid);

		this.server_state.applyDebugState ();

		// for debug purposes
		System.out.println ("Executing balance req with reqid " + reqid);

		BalanceResult balance = this.server_state.getBalance (minExecutedInstance, uid);
		boolean result = balance.balance () != -1;

		// for debug purposes
		System.out.println ("Result for balance request is ready: " + reqid);

		DidaTradeMain.BalanceReply response = DidaTradeMain.BalanceReply.newBuilder ().setReqid (reqid).setResult (result).setBalance (balance.balance ())
				.setInstance (balance.lastExecutedInstance ()).build ();

		responseObserver.onNext (response);
		responseObserver.onCompleted ();
	}

